import type { HTMLAttributes, ReactNode } from 'react'
import { cn } from '@/react/lib/cn'

// The site's card: a #141414 fill on black with square corners, no border and no shadow, 24px in. `title` is an Agencidev Sans
// Display card title (24/28 at 400, as the site's resource cards), `description` a dim (#B6B6B6) line of ABC Diatype under it, the children the body, and `actions` a row at the foot (a full
// width button in the plan card).
export interface CardProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  title?: ReactNode
  description?: ReactNode
  /** Buttons or links at the foot. */
  actions?: ReactNode
}

export function Card({ title, description, actions, className, children, ...rest }: CardProps) {
  return (
    <div data-ds="card" {...rest} className={cn('flex flex-col gap-6 rounded-container bg-surface-raised p-6 text-fg', className)}>
      {(title || description) && (
        <div className="flex flex-col gap-2">
          {title && <h3 className="type-heading-3">{title}</h3>}
          {description && <p className="type-body text-fg-soft">{description}</p>}
        </div>
      )}
      {children}
      {actions && <div className="mt-2 flex flex-wrap gap-3">{actions}</div>}
    </div>
  )
}

export default Card

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

